function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(74001);
var T0=Date.now();
var H=3;
var work={cpu:1000,mem:500,io:200};
var opts=[];for(var i=0;i<H;i++)opts.push({name:"hw-"+i,cpu:0.5+R()*2,mem:0.5+R()*2,io:0.5+R()*2,cost:100+Math.floor(R()*900)});
var res=opts.map(function(o){var t=work.cpu/o.cpu+work.mem/o.mem+work.io/o.io;return{name:o.name,est_time:+t.toFixed(1),cost:o.cost};});
res.sort(function(a,b){return a.est_time-b.est_time;});
console.log(JSON.stringify({id:"JAH-APX74-000001",ok:true,metrics:{options:H,best:res[0].name,best_est_time:res[0].est_time,worst_est_time:res[H-1].est_time,improvement_pct:+((1-res[0].est_time/res[H-1].est_time)*100).toFixed(1)},ms:Date.now()-T0}));

